import { ActionType, Character, DiceRoll, EffectHandler, StatusBehavior, random } from '@pimpampum/engine';
import { SkillDefinition, action, d, ICON_PREFIX } from '../../players/types.js';
import { standingCoverAction } from '../../players/cards/index.js';
import { num } from '../../players/effects/helpers.js';

/** The skill all explosive ordnance belongs to (content may know its own ids). */
export const EXPLOSIVE_SKILL_ID = 'enginyer-explosius@cal';
const CHARGE_STATUS = 'carregues';

/** Bandolier size: a finite per-combat pool, min(6, 2 + level). TODO(balance) */
export function maxCharges(actor: Character): number {
  const lvl = actor.getSkillLevel(EXPLOSIVE_SKILL_ID);
  return Math.min(6, 2 + lvl);
}

/** Current càrregues; falls back to the full bandolier if not yet initialised. */
function charges(actor: Character): number {
  return actor.getStatusValue(CHARGE_STATUS, maxCharges(actor));
}

/**
 * The bandolier RELOADS: at the end of a round in which no charge was spent,
 * one comes back (up to the full bandolier). A pause is a reload. Without it the
 * engineer ran dry in long fights and was left with barricades and smoke, so
 * those fights ran longer still — the kit's p90 sat at 11 rounds (NEXT-STEPS §26).
 */
const BANDOLER: StatusBehavior = {
  onRoundEnd(ctx) {
    if (ctx.entry.data?.['spentRound'] === ctx.engine.round) return;
    if (ctx.entry.value < maxCharges(ctx.holder)) ctx.entry.value++;
  },
};

function setCharges(actor: Character, n: number, spentRound?: number): void {
  actor.setStatus(CHARGE_STATUS, Math.max(0, n), -1, { spentRound }, BANDOLER);
}

/**
 * Enginyer d'Explosius — a military demolitions engineer who fights from a finite
 * bandolier of càrregues (charges). Ordnance spends charges, and a round without
 * spending any reloads one; smoke is free. All handlers and the `encegat` / `camp-minat` status behaviours live
 * below, on this SkillDefinition.
 */
const ENGINYER_EFFECTS: Record<string, EffectHandler> = {
  // Spend `amount` càrregues to play. Gates availability, spends on play, and
  // seeds the bandolier at combat start so the pool shows from turn one.
  'charge_cost@cal': {
    onCombatStart(ctx) {
      if (!ctx.source.hasStatus(CHARGE_STATUS)) setCharges(ctx.source, maxCharges(ctx.source));
    },
    canPlay(actor, params) {
      return charges(actor) >= num(params, 'amount', 1);
    },
    onPlay(ctx) {
      setCharges(ctx.source, charges(ctx.source) - num(ctx.params, 'amount', 1), ctx.engine.round);
    },
  },

  // Bomba de fum: a smoke screen blinds the enemy team for the rest of the round.
  // Each blinded enemy attack scatters via the `encegat` status behaviour below.
  // Free — smoke is a separate pouch.
  'smoke@cal': {
    getTargetRequirement() { return 'none'; },
    onResolve(ctx) {
      const turns = num(ctx.params, 'turns', 1);
      const below = num(ctx.params, 'below', 10);
      for (const e of ctx.engine.enemiesOf(ctx.source)) e.setStatus('encegat', 1, turns, { below }, ENCEGAT);
      ctx.engine.log('focus', 'Una cortina de fum encega els enemics!', ctx.source.team);
    },
    aiWeight(ctx) { return ctx.enemies.length >= 2 ? 1.5 : 0.4; },
  },

  // Camp minat: seed the ground with mines. Stored as a pool on the layer; an
  // attacking enemy trips one via the `camp-minat` status behaviour below.
  // Costs càrregues via a paired charge_cost effect.
  'lay_minefield@cal': {
    getTargetRequirement() { return 'none'; },
    onResolve(ctx) {
      const mines = num(ctx.params, 'mines', 3);
      const sides = num(ctx.params, 'damageSides', 6);
      ctx.source.setStatus('camp-minat@cal', mines, -1, { damage: new DiceRoll(1, sides), trip: num(ctx.params, 'trip', 10) }, CAMP_MINAT);
      ctx.engine.log('focus', `${ctx.source.name} sembra ${mines} mines al terreny.`, ctx.source.team);
    },
    aiWeight(ctx) { return ctx.enemies.length >= 1 ? 1.4 : 0; },
  },

  // Traca final: an all-enemies ATTACK that spends the ENTIRE bandolier —
  // Nd4 with N = càrregues spent, capped at `max` dice (the surplus burns
  // off; erupció pattern: the count is stamped in a round-scoped status and
  // injected at roll time).
  'empty_bandolier@cal': {
    canPlay(actor) { return charges(actor) >= 1; },
    onPlay(ctx) {
      const total = charges(ctx.source);
      const n = Math.min(total, num(ctx.params, 'max', 99));
      setCharges(ctx.source, 0);
      ctx.source.setStatus('traca-encesa', n, 1);
      ctx.engine.log('attack', `${ctx.source.name} encén la traca final amb ${total} càrregues!`, ctx.source.team);
    },
    modifyAttack(ctx) {
      const n = ctx.source.getStatusValue('traca-encesa', 0);
      if (n > 0 && ctx.attackMods) {
        ctx.attackMods.extraDamageDice.push(new DiceRoll(n, num(ctx.params, 'sides', 6)));
      }
    },
    aiWeight(ctx) {
      // Hoard, then unleash: more value with a full bandolier and many targets.
      const n = charges(ctx.actor);
      return n >= 3 ? n * 0.5 * Math.max(1, ctx.enemies.length) : 0.2;
    },
  },
};

// Smoke: the blinded holder fires through the haze — on a d20 ≤ 10 the shot
// lands on a random living combatant instead of its intended target. Holders
// who perceive without sight (any ignoresConcealment status) aim true.
const ENCEGAT: StatusBehavior = {
  redirectAttackTarget(ctx, intended) {
    if (ctx.holder.statusRefs().some(r => r.entry.behavior?.ignoresConcealment?.(r))) return intended;
    if (ctx.engine.rollDie(20) > num(ctx.entry.data ?? {}, 'below', 10)) return intended;
    const pool = [...ctx.engine.livingTeam(0), ...ctx.engine.livingTeam(1)].filter(c => c !== ctx.holder);
    if (pool.length === 0) return intended;
    const pick = pool[Math.floor(random() * pool.length)];
    if (pick !== intended) ctx.engine.log('info', `${ctx.holder.name} dispara a cegues dins el fum i apunta cap a ${pick.name}!`, ctx.holder.team);
    return pick;
  },
};

// Minefield pool on the layer (persists even if the layer has fallen): the
// first live minefield gives each attacking enemy a d20 ≤ 10 chance to trip a
// mine, take its blast (armour-ignored) and spend it. One check per attack.
const CAMP_MINAT: StatusBehavior = {
  /**
   * Mines still in the ground are damage already paid for.
   *
   * `positionScore` sees only PV, bodies and fatigue, so a laid minefield read
   * as nothing at all and Camp minat was played on 1.9% of the turns it was
   * legal. Priced at roughly one mine's average blast per charge left, against
   * a body's health, and deliberately shy of what they WILL do: a mine only
   * pays if someone steps on it.
   */
  positionValue(ref) {
    return Math.min(0.6, 0.15 * Math.max(0, ref.entry.value));
  },
  onEnemyAttackAction(ctx, attacker) {
    if (ctx.entry.value <= 0) return false;
    if (ctx.engine.rollDie(20) <= num(ctx.entry.data ?? {}, 'trip', 10)) {
      const dice = ctx.entry.data?.['damage'] as DiceRoll | undefined;
      const dmg = dice ? dice.roll() : 1;
      ctx.engine.log('trap', `${attacker.name} trepitja una mina! (${dmg} dany)`, attacker.team);
      ctx.engine.applyPvLoss(attacker, dmg, undefined);
      ctx.entry.value--;
      if (ctx.entry.value <= 0) {
        ctx.holder.clearStatus('camp-minat@cal');
        ctx.engine.log('info', 'El camp de mines s’esgota.', ctx.holder.team);
      }
    }
    return true; // one minefield check per attack
  },
};

